    pub fn get_generator_for_name(world: &str, name: Option<String>, output: Option<JRef<dyn CommandSender>>) -> Option<JRef<dyn ChunkGeneratorTrait>> {
        let mut result = None;
        let output: JRef<dyn CommandSender> = match output {
            Some(output) => output,
            None => Bukkit::get_console_sender(),
        };

        if let Some(name) = name {
            let split: Vec<&str> = name.splitn(2, ':').collect();
            let id = if split.len() > 1 { Some(split[1].to_string()) } else { None };
            let plugin = Bukkit::get_plugin_manager().get_plugin(split[0]);

            match plugin {
                None => output.send_message(&format!("Could not set generator for world '{}': Plugin '{}' does not exist", world, split[0])),
                Some(plugin) if !plugin.is_enabled() => output.send_message(&format!(
                    "Could not set generator for world '{}': Plugin '{}' is not enabled",
                    world,
                    plugin.get_description().get_full_name()
                )),
                Some(plugin) => result = plugin.get_default_world_generator(world, id),
            }
        }

        result
    } // paper-api/src/main/java/org/bukkit/WorldCreator.java:635
